// v2.13 算法移植，坐标使用运行时的 32px 逻辑轨道。
const motionPreference = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null;

return {
  init({ h }) {
    const peak = h.createCanvas(48, 48);
    const ctx = peak.getContext("2d");
    const glow = ctx.createRadialGradient(24, 24, 0, 24, 24, 24);
    glow.addColorStop(0, "#ffffff");
    glow.addColorStop(1, "rgba(255, 255, 255, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, 48, 48);
    return { lastTime: null, flashTime: 0, wasMax: false, afterglow: 0, peak };
  },
  draw(ctx, s) {
    const { width, height, pal, dark, state } = s;
    const thumbX = Math.max(0, Math.min(s.end, width));
    if (thumbX <= 0) return;
    const L2 = s.high;
    const L3 = s.max;
    const reduced = Boolean(motionPreference?.matches);
    const time = reduced ? 0 : s.time;
    const burstT = reduced ? 0 : s.burst;
    const isBursting = burstT > 0;
    const isMaxEffort = L3 >= 0.94;
    const secondary = s.monet?.enabled ? s.monet.secondary : pal;
    const cruisePulse = isMaxEffort ? 0.5 + 0.5 * Math.sin(time * 1.8) : 0;

    // 用运行时已调整流速的时间推进粒子，流速归零时定格。
    const elapsed = state.lastTime === null || reduced ? 0 : Math.max(0, time - state.lastTime);
    // 连续高亮脉冲保持在每秒三次以下。
    state.flashTime = state.lastTime === null ? time : state.flashTime + Math.min(elapsed, s.dt * 0.033);
    const flashTime = reduced ? 0 : state.flashTime;
    state.lastTime = time;
    const currentRatio = s.ratio ?? thumbX / Math.max(1, width);

    ctx.globalCompositeOperation = dark ? "lighter" : "source-over";
    state.afterglow = state.wasMax && !isMaxEffort ? 1 : Math.max(0, state.afterglow - s.dt / 24);
    state.wasMax = isMaxEffort;
    const afterglowT = reduced ? 0 : state.afterglow;

    const bars = 24;
    const pitch = thumbX / bars;
    const barW = pitch - Math.min(2, pitch * 0.45);
    for (let b = 0; b < bars; b++) {
      const bx = b * pitch;
      const noise = Math.abs(Math.sin(flashTime * 4 + b * 0.65));
      const barH = height * (0.2 + 0.75 * noise * currentRatio);
      ctx.fillStyle = (b % 2 === 0 ? pal : secondary).light(0.85);
      ctx.fillRect(bx, height - barH, barW, barH);
    }

    // High：柱顶峰值点亮
    if (L2 > 0.01) {
      for (let b3 = 0; b3 < bars; b3++) {
        const noise3 = Math.abs(Math.sin(flashTime * 4 + b3 * 0.65));
        const bh3 = height * (0.2 + 0.75 * noise3 * currentRatio);
        ctx.fillStyle = "rgba(255, 255, 255, " + (0.8 * noise3 * L2) + ")";
        ctx.fillRect(b3 * pitch, height - bh3, barW, 1.6);
      }
    }
    // Max：柱顶光晕 + 低频脉冲带
    if (L3 > 0.01) {
      const baseAlpha = ctx.globalAlpha;
      const glowRadius = barW * 2.2;
      for (let b4 = 0; b4 < bars; b4++) {
        const noise4 = Math.abs(Math.sin(flashTime * 4 + b4 * 0.65));
        if (noise4 < 0.55) continue;
        const bx3 = b4 * pitch + barW / 2;
        const by3 = height - height * (0.2 + 0.75 * noise4 * currentRatio);
        ctx.globalAlpha = baseAlpha * 0.75 * (noise4 - 0.5) * 2 * L3;
        ctx.drawImage(state.peak, bx3 - glowRadius, by3 - glowRadius, glowRadius * 2, glowRadius * 2);
      }
      ctx.globalAlpha = baseAlpha;
      const lowH = height * 0.34 * (0.55 + 0.45 * Math.sin(time * 2.2));
      ctx.fillStyle = pal.light(0.16 * L3);
      ctx.fillRect(0, height * 0.5 - lowH / 2, thumbX, lowH);
    }

    // 【L2 结构层】克制的顶边高光与丝滑掠过扫光，让 High 更有层次又不遮挡主体动效
    if (L2 > 0.01) {
      const topSheen = ctx.createLinearGradient(0, 0, thumbX, 0);
      topSheen.addColorStop(0, "rgba(255, 255, 255, 0)");
      topSheen.addColorStop(0.5, `rgba(255, 255, 255, ${(0.18 * L2).toFixed(3)})`);
      topSheen.addColorStop(1, `rgba(255, 255, 255, ${(0.36 * L2).toFixed(3)})`);
      ctx.fillStyle = topSheen;
      ctx.fillRect(0, 1.0, thumbX, 1.2);

      const sweepX = ((time * 0.36) % 1) * (thumbX + 150) - 75;
      const sweepGrad = ctx.createLinearGradient(sweepX - 50, 0, sweepX + 50, 0);
      sweepGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      sweepGrad.addColorStop(0.5, `rgba(255, 255, 255, ${(0.18 * L2).toFixed(3)})`);
      sweepGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = sweepGrad;
      const left = Math.max(0, sweepX - 50);
      const right = Math.min(thumbX, sweepX + 50);
      if (right > left) ctx.fillRect(left, 0, right - left, height);
    }

    // 【L3 高能层】美学克制版 Max 光冠：径向柔核 + 6 道细光晕 + 2 圈柔波，告别杂乱激光与方块噪点
    if (L3 > 0.01) {
      const crownR = Math.max(height * 1.45, 38);
      const crown = ctx.createRadialGradient(thumbX, height * 0.5, 0, thumbX, height * 0.5, crownR);
      crown.addColorStop(0, `rgba(255, 255, 255, ${(0.42 * L3 * (0.88 + 0.12 * cruisePulse)).toFixed(3)})`);
      crown.addColorStop(0.45, pal.light(0.24 * L3));
      crown.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = crown;
      ctx.beginPath();
      ctx.arc(thumbX, height * 0.5, crownR, 0, Math.PI * 2);
      ctx.fill();

      const rayR = Math.max(height * 0.95, 28);
      for (let r = 0; r < 6; r++) {
        const ra = time * 1.15 + (r / 6) * Math.PI * 2;
        const rl = rayR * (0.55 + 0.45 * Math.sin(time * 2.1 + r * 1.4));
        const rayGrad = ctx.createLinearGradient(thumbX, height * 0.5,
          thumbX + Math.cos(ra) * rl, height * 0.5 + Math.sin(ra) * rl);
        rayGrad.addColorStop(0, `rgba(255, 255, 255, ${(0.34 * L3).toFixed(3)})`);
        rayGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
        ctx.strokeStyle = rayGrad;
        ctx.lineWidth = 1.1;
        ctx.beginPath();
        ctx.moveTo(thumbX, height * 0.5);
        ctx.lineTo(thumbX + Math.cos(ra) * rl, height * 0.5 + Math.sin(ra) * rl);
        ctx.stroke();
      }

      for (let k = 0; k < 2; k++) {
        const ph = (time * 0.68 + k * 0.5) % 1;
        const rr = ph * width * 0.42;
        const aa = (1 - ph) * 0.30 * L3;
        if (aa < 0.02) continue;
        ctx.strokeStyle = `rgba(255, 255, 255, ${aa.toFixed(3)})`;
        ctx.lineWidth = 1.5 * (1 - ph) + 0.5;
        ctx.beginPath();
        ctx.arc(thumbX, height * 0.5, rr, Math.PI * 0.5, Math.PI * 1.5);
        ctx.stroke();
      }

      const rimGrad = ctx.createLinearGradient(0, 0, thumbX, 0);
      rimGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      rimGrad.addColorStop(Math.min(1, Math.max(0, 0.55 + 0.3 * Math.sin(time * 0.8))), `rgba(255, 255, 255, ${(0.32 * L3).toFixed(3)})`);
      rimGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = rimGrad;
      ctx.fillRect(0, 0.6, thumbX, 1.2);
      ctx.fillRect(0, height - 1.8, thumbX, 1.2);
    }

    if (isBursting) {
      const shockRadius = (1 - burstT) * width * 0.85;
      ctx.save();
      ctx.strokeStyle = dark ? `rgba(255, 255, 255, ${burstT * 0.85})` : pal.main(burstT * 0.75);
      ctx.lineWidth = 3.5 * burstT;
      ctx.beginPath();
      ctx.arc(thumbX, height / 2, shockRadius, 0, Math.PI * 2);
      ctx.stroke();

      // 全轨高光冲洗 (Flash Wash)
      ctx.fillStyle = dark ? `rgba(255, 255, 255, ${burstT * 0.35})` : `rgba(255, 255, 255, ${burstT * 0.2})`;
      ctx.fillRect(0, 0, thumbX, height);
      ctx.restore();
    }

    // ---------------------------------------------------------
    // ③ 降档余韵尾迹 (Afterglow: 0.4s)
    // ---------------------------------------------------------
    if (afterglowT > 0) {
      ctx.save();
      ctx.fillStyle = pal.light(afterglowT * 0.25);
      ctx.fillRect(0, 0, thumbX, height);
      ctx.restore();
    }
  }
};
